function Toggle({ on, onChange, defaultOn = false }) {
  const isControlled = on !== undefined;
  const [internalOn, setInternalOn] = useState(defaultOn);

  const currentOn = isControlled ? on : internalOn;

  const toggle = () => {
    if (!isControlled) {
      setInternalOn(!currentOn);
    }
    if (onChange) {
      onChange(!currentOn);
    }
  };

  return (
    <button onClick={toggle} className={currentOn ? 'on' : 'off'}>
      {currentOn ? 'ON' : 'OFF'}
    </button>
  );
}

